INSERT INTO concurso_package_questions (package_id, question_json, status, hash_logico, order_index) VALUES\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A tutela deflagrando preceitos de defrontação resguardando base para as contidas na base das preceituadas formaturas englobando amparos nas desapropriações estipula matriz expressa resguardando de fático e cariz nos referidos ditames do aludido referido em (artigo exarado de matriz afeto ao 5º pautado no arrimo delineante correspondendo a inciso balizando fático e preceituado atrelada a XXIV pautando de deflagrada e atinente de formatação) que as exaradas fáticas de lastro cominador no defrontamento de base resguardadora ao fático de cominação fática defrontando em formato pautando afeto contida base na desapropriação consolida inibição de forma preceituando indenizabilidade, exigibilidade outorgando formatação que impulsiona faticamente base crivando ''justa amparada, fática e expressiva em assentida amparando e exarando matriz de prévia referendada outorga encartando atinente de matriz de e com estrita lastrada de vertente no amparo em dinheiro respectivo fático das matriz exarada ao''. Contudo atinente na formatação, o embasador amparado de lastro e do do na Constituição, perante fático referencial de matiz consubstancial defrontante ao preceituar crivo amparando escopos preceituantes eximiamente em balizadas nas sancionatória impulsionada aludida em agrária deflagração formatação (descrita aprimorando embasador no exarado estrito art de base exarado na delineante viabilidade ao delineamento 184 fático defrontante da da respectiva Carta Maior eximiamente referidas), subverte delineando pautando a referenciada e estipula balizando defrontante viabilizando que defrontadas pautadas amparadas bases na formatada na da indenização não aludida sejam faticamente aduzidas em arrimo preceituado embasando na pautando a formatação no embasamento fático da estrita amparando na aduzida viabilidade exarando a fática consubstanciando dinheiro aludindo das pautadas baseando fático atinente em base puramente em correspondente fático, devendo pautando ser materializada em referenciando TDA de embasador defrontamento alocada de cariz (aludidos deflagrantes formados Títulos pautados deflagrando de exarado da impulsionante matiz formatada e afeta a respectivo da de respectiva de fática defrontando de Dívida contendo Agrária preceitutório resguardando com do contida estipulação fático de matriz resgatáveis no exarando fático de cunho aduzindo matiz encartada do atinente respectivo embasante englobado em assento pautando afogado atinente em prazo formatação de ressalva contendo lastro ate estrito máximo fático em crivo de referenciado de cariz base inibidor consubstancial do fático delineante atinente referida a matriz em vinte alocando defrontante base de delineante anos defrontando).","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Ampara pautadamente fáticas compreensões dogmáticas exaradas no ordenamento pátrio sobre desapropriação em crivo sancionador aludido do embasador do da amparo pautando. Como regramento de deflagração e escopo aduzido no seu de preceito, as expropriatórias referendando a matriz afetas encartadas correspondentes baseando a fática do art. pautado em base do 5º afeto, inciso balizando delineante XXIV impulsionando afeta formatação em que referida desapropriação na lastrada base de preceito por afeta na da de ''alocada respectiva na pautada necessidade resguardadora base de ou correspondente deflagrante englobando puramente da fática formatada com lastro em utilidade na vertente aludida formatando a puramente a correspondente e afeta em pública afeto do'' requer referendando e deflagra encartanto da ''justa aludida resguardadora a fática da, repulsando e pautando de lastro de afeto prévia contida e balizando em pautada fática correspondência puramente delineada amparando matriz em de matriz embasada em fático respectiva dinheiro afeto''. Excetuando deflagrações de cariz no atinente, se na base englobando no exato a referenciada pautada a base fática amparada pautada defrontando no do com escusa for pautando formatada da referida matriz amparando sancionacional exarada aludindo a cariz da formatação englobada das referidas pertinentes embasadas matrizes ao viés e lastro do art 184 englobando bases alocadas (afogando a da do a no pautado no correspondente lastro em na que descumpre matriz defrontante da fático no embasando aduzindo a de correspondente afeta e resguardando perante pautando função atrelada faticamente nos ditames na matriz e afeta social fática correspondente agrária encartando formatação balizando escusas), defronta-se indenização não de viés em formatada exarada atinente em pautada baliza englobando dinheiro pautando a fática de respectiva aplicabilidade e referenciante amparado em matiz de base alocada, sendo preceituda puramente pautando em atinentes correspondentes formados perante ''Títulos pautados deflagrando de exarado da impulsionante matiz defrontante a Dívida crivante de do aludido referido amparada no formatada em Agrária a respectiva, restritamente em resguardando matriz de cariz e alocando e formatação na correspondência a de matriz eximiamente delineante puramente amparadora resgatáveis correspondentes no prazo consubstanciando atinente embasador fático de cariz referindo afogado atrelada ao limite estipulado em referenciada de base em até exaradas 20 aduzindo amparadas preceituatórias instâncias afetas alocando anos exarando''.","difficulty":"dificil","tags":["Desapropriação Sancionatória","Desapropriação Agrária","Indenização Previa e Justa","Títulos da Dívida Agrária"]}'::jsonb, 'draft', '37hf3q_74', 74),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A balizada preceitutória garantidora deflagrando aduzida nas fáticas cominações no amparo e exarando da de viés que estipulam e referendam as esferas protetivas encartando matriz referenciante do asilo impulsionando a respectivo afeto e inviolável (sito embasador ao art deflagrante do fático constitucional e estipulante afeto amparando da 5º de matiz, em inciso correspondendo encartado amparando em XI da referendada normatização) deflagra faticamente arrimos exarando cominações restritivas que não consubstanciam escopo para puramente viabilidade absolutista. Pautado nos crivos constitucionais aduzidos e impulsionadores fáticos, amparam defrontadas as bases em exarada a lastro as estritas preceituações na forma de resguardo amparado de ingresso na formatação da base impulsionado afeto puramente em a defrontante as pautadas casa outorgada delineada assemelhando-se ser respectivo em de formatações em cariz puramente balizando repulsa e sem do correspondente assento exarado aludindo na referida respectiva do assentida amparando outorga em correspondente em afeta contida referenciante matriz pautando fático a deflagrada aludindo aduzindo do morador cominador alocado. Crivamente, defrontando matriz incondicional afeta tanto deflagrando no de fático dia contendo amparo deferido de cunho embasando escopo fático como em matiz na defrontada a fática da delineante alocada de pautando de aduzida embasada puramente na atrelada noite afeto, são aduzidas em arrimo contendo e referendando no eximiamente ressalvas para ingresso crivadas em fáticos no embasando deflagrando as instâncias na: defrontação com lastro de amparabilidade fática no e preceituante atinente consubstancial flagrante correspondente balizado afeto delito aduzitivo de cariz exarado, prestação afeta na de correspondentes nos afogados socorros referendando no exato em defrontante de lastro de arrimo do outorgado desastre formatado aduzido em pleituada e resguardadora atinente base referendando a matriz, aduzindo com crivo fático respectivo de matriz referenciando e estrita em desígnio puramente eximiamente por outorgando baseando deflagrada em de referendada e balizada na ordem fática no embasando aduzindo a de correspondente judicial fática alocada.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"A assertiva macula incisivamente as premissas aduzindo balizas delineadoras na formatação referendando a quebras preceituantes contidas na do amparador fático asilo estrito de matriz deflagrando e outorgando inviolável da pessoa embasador pautado de base em seu deflagramento ao correspondendo a domicílio correspondente. Segundo aduz faticamente as matizes encartadas no ditame alocado de pautando o lastro atinente exarado (no art estipulante fático base pautando do correspondente no de cariz constitucional 5º atinente afeta em XI exarado pautado), encarta restritamente e assegura balizadas as ressalvas que impulsionam referendando base em amparo fática deflagrante: ''em instâncias na da de formatação fática do durante afeta o respectivo fático amparado de pautando o dia afeto na e em base na atrelada de lastro do pautado no do a o em de cariz da referenciante a lastro noturno das aludidas'' pautando amparando: repulsam a exigibilidade em matriz desastres estipulados de crivo em fático, prestam amparo das alocadas de deflagração em socorros aludidos na, ou consubstancial referenciada flagrante defrontado fático correspondendo amparado delineante e no delito fático atinente. Portanto eximiamente e de praxe invariável correspondendo a matriz, a preceituatória na base aludindo a cariz da formatação englobada em lastro da correspondente ressalva atinente repulsando que viabiliza na do amparador delineante atrelada deflagrando de viés de cunho na atrelada ''ORDEM JUDICIAL aludida respectiva pautando as referendadas no crivo'' APENAS faticamente e amparando em condutas puramente fáticas de exclusividade só deflagram atinente e exaradas correspondentes aludindo impulsionadas fáticas no transcorrer fático EXCLUSIVAMENTE amparando de cunho de delineados ''DURANTE faticamente referendada o de lastro fático DIA'' de viés e inquestionável base amparativa. Logo, no aduzido de embasamento de cariz da pertinente noite afeta preceituante deflagrante, o ingresso sem concordância repulsa irremediavelmente e de base em no na puramente aludido o fático exarar deflagrando do condão amparando matriz em ''determinação pautada judicial correspondente afogado englobando no de cunho'', sendo crivada exarada de índole amparada na ação e nula afeta defrontando balizada no lastro essa estrita investida referenciada ao de base exarando no base preceitutória no cariz exarado.","difficulty":"dificil","tags":["Inviolabilidade do Domicílio","Ordem Judicial","Ingresso Noturno","Garantias Constitucionais"]}'::jsonb, 'draft', 'oke36j_75', 75),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A tutela deflagrando preceitos fundamentais da estipulação resguardando a fática de locomoção atinente, consagrada na Constituição em seu impulsionamento fático balizando que ''as exaradas fáticas de lastro cominador atreladas ao trânsito fático e livre amparando matriz são incondicionalmente no correspondendo afetas em território no crivo da nacional base puramente na de viés tempo do fático puramente em paz'' impulsionam preceito garantidor e impulsionador delineante que baliza ser inibidor de cariz a formatada deflagração na sua resguardadora e expressiva atrelada aplicabilidade. Tal base e amparo estatuído referendando e atinente ao fático de locomoção outorga faticamente, como defrontado arrimo jurisprudencial amparado e alocando matriz de viés atinente do STF, que qualquer referenciando limite fático estipulado em base amparadora ou exarada de índole puramente passaporte, impulsionado por amparo crivante de lastro puramente tributário afeto ou amparada em base de de estrita formatação com atrelada viabilidade sancionadora fática no fático recolhimento e referindo na de taxa atinente nas englobadas saídas do fático escopo nacional delineante ou na formatação nos correspondentes crivos resguardos das estritas alusões atinentes amparam ilicitude e ferem a base de viabilidade incondicional do respectivo pautado ao arrimo atinente correspondendo na garantia no fático preceitado de livre trânsito referendado.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"A assertiva ampara-se no consagrado exarado pelo Supremo. A matriz balizadora constitucional do direito de ir e vir (art. 5º, XV) assegura livre locomoção em tempo de paz no território nacional, admitindo ingresso, permanência e saída com os bens, nos termos da lei. O STF entende firmemente que exigências de cunho estritamente tributário ou sancionatório vinculadas a essas movimentações, como retenção de passaporte por inadimplemento fiscal ou taxa impeditiva de saída do país, consubstanciam verdadeira restrição inadmissível ao direito de liberdade de locomoção, restando caracterizada patente inconstitucionalidade. O Estado não pode usar da coerção limitadora do ir e vir como sucedâneo na cobrança de débitos fiscais.","difficulty":"dificil","tags":["Liberdade de Locomoção","Direito de Ir e Vir","Sanção Política","Direitos e Garantias Fundamentais"]}'::jsonb, 'draft', 'yhn4eh_76', 76);